const int led_array[8] = {0, 1, 2, 3, 4, 5, 6, 7}; // Pins connected to LEDs

void setup() {
  for (int i = 0; i < 8; i++) {
    pinMode(led_array[i], OUTPUT);
  }
}

void loop() {
  cylonBounce(100, 2);      // Knight Rider scanning effect
  centerInOut(100, 2);      // Expand from center to edges, then collapse back
  binaryCounter(150);       // Counts from 0 to 255 in binary
  alternatingFlash(150, 4);  // Toggles odd and even LEDs
  stackingBar(80);          // Tetris-style stacking effect
}

// Helper to turn off all LEDs
void clearLeds() {
  for (int i = 0; i < 8; i++) {
    digitalWrite(led_array[i], LOW);
  }
}

// Pattern 1: Cylon / Knight Rider Bounce
void cylonBounce(int delayTime, int repeats) {
  for (int r = 0; r < repeats; r++) {
    for (int i = 0; i < 8; i++) {
      clearLeds();
      digitalWrite(led_array[i], HIGH);
      delay(delayTime);
    }
    for (int i = 6; i > 0; i--) {
      clearLeds();
      digitalWrite(led_array[i], HIGH);
      delay(delayTime);
    }
  }
  clearLeds();
}

// Pattern 2: Center-Out and Center-In Expansion
void centerInOut(int delayTime, int repeats) {
  for (int r = 0; r < repeats; r++) {
    // Expand from center
    for (int i = 0; i < 4; i++) {
      clearLeds();
      digitalWrite(led_array[3 - i], HIGH);
      digitalWrite(led_array[4 + i], HIGH);
      delay(delayTime);
    }
    // Collapse to center
    for (int i = 2; i >= 0; i--) {
      clearLeds();
      digitalWrite(led_array[3 - i], HIGH);
      digitalWrite(led_array[4 + i], HIGH);
      delay(delayTime);
    }
  }
  clearLeds();
}

// Pattern 3: 8-Bit Binary Counter (0 - 255)
void binaryCounter(int delayTime) {
  for (int count = 0; count < 256; count++) {
    for (int bit = 0; bit < 8; bit++) {
      int state = (count >> bit) & 1;
      digitalWrite(led_array[bit], state);
    }
    delay(delayTime);
  }
  clearLeds();
}

// Pattern 4: Alternating Odd / Even Flashing
void alternatingFlash(int delayTime, int repeats) {
  for (int r = 0; r < repeats; r++) {
    // Evens ON, Odds OFF
    for (int i = 0; i < 8; i++) {
      digitalWrite(led_array[i], (i % 2 == 0) ? HIGH : LOW);
    }
    delay(delayTime);

    // Odds ON, Evens OFF
    for (int i = 0; i < 8; i++) {
      digitalWrite(led_array[i], (i % 2 != 0) ? HIGH : LOW);
    }
    delay(delayTime);
  }
  clearLeds();
}

// Pattern 5: Tetris-style Stacking Fill
void stackingBar(int delayTime) {
  clearLeds();
  for (int limit = 7; limit >= 0; limit--) {
    for (int i = 0; i <= limit; i++) {
      digitalWrite(led_array[i], HIGH);
      delay(delayTime);
      if (i < limit) {
        digitalWrite(led_array[i], LOW);
      }
    }
  }
  delay(500);
  clearLeds();
}
